public static Object add(Object arg1, Object arg2) throws NoSuchMethodException {
        int code1 = typeCode(arg1);
        int code2 = typeCode(arg2);
        int maxcode = (code1 < code2) ? code2 : code1;
        if (maxcode <= INT) {
            return boxToInteger(unboxCharOrInt(arg1, code1) + unboxCharOrInt(arg2, code2));
        }
        if (maxcode <= LONG) {
            return boxToLong(unboxCharOrLong(arg1, code1) + unboxCharOrLong(arg2, code2));
        }
        if (maxcode <= FLOAT) {
            return boxToFloat(unboxCharOrFloat(arg1, code1) + unboxCharOrFloat(arg2, code2));
        }
        if (maxcode <= DOUBLE) {
            return boxToDouble(unboxCharOrDouble(arg1, code1) + unboxCharOrDouble(arg2, code2));
        }
        throw new NoSuchMethodException();
    }

Tries to decrement active count (sometimes implicitly) and
possibly release or create a compensating worker in preparation
for blocking. Fails on contention or termination. Otherwise,
adds a new thread if no idle workers are available and either
pool would become completely starved or: (at least half
starved, and fewer than 50% spares exist, and there is at least
one task apparently available). Even though the availability
check requires a full scan, it is worthwhile in reducing false
alarms.

@param task if non-null, a task being waited for
@param blocker if non-null, a blocker being waited for
@return true if the caller can block, else should recheck and retry
final boolean tryCompensate(ForkJoinTask<?> task, ManagedBlocker blocker) {
        int pc = parallelism, e;
        long c = ctl;
        WorkQueue[] ws = workQueues;
        if ((e = (int)c) >= 0 && ws != null) {
            int u, a, ac, hc;
            int tc = (short)((u = (int)(c >>> 32)) >>> UTC_SHIFT) + pc;
            boolean replace = false;
            if ((a = u >> UAC_SHIFT) <= 0) {
                if ((ac = a + pc) <= 1)
                    replace = true;
                else if ((e > 0 || (task != null &&
                                    ac <= (hc = pc >>> 1) && tc < pc + hc))) {
                    WorkQueue w;
                    for (int j = 0; j < ws.length; ++j) {
                        if ((w = ws[j]) != null && !w.isEmpty()) {
                            replace = true;
                            break;   // in compensation range and tasks available
                        }
                    }
                }
            }
            if ((task == null || task.status >= 0) && // recheck need to block
                (blocker == null || !blocker.isReleasable()) && ctl == c) {
                if (!replace) {          // no compensation
                    long nc = ((c - AC_UNIT) & AC_MASK) | (c & ~AC_MASK);
                    if (U.compareAndSwapLong(this, CTL, c, nc))
                        return true;
                }
                else if (e != 0) {       // release an idle worker
                    WorkQueue w; Thread p; int i;
                    if ((i = e & SMASK) < ws.length && (w = ws[i]) != null) {
                        long nc = ((long)(w.nextWait & E_MASK) |
                                   (c & (AC_MASK|TC_MASK)));
                        if (w.eventCount == (e | INT_SIGN) &&
                            U.compareAndSwapLong(this, CTL, c, nc)) {
                            w.eventCount = (e + E_SEQ) & E_MASK;
                            if ((p = w.parker) != null)
                                U.unpark(p);
                            return true;
                        }
                    }
                }
                else if (tc < MAX_CAP) { // create replacement
                    long nc = ((c + TC_UNIT) & TC_MASK) | (c & ~TC_MASK);
                    if (U.compareAndSwapLong(this, CTL, c, nc)) {
                        addWorker();
                        return true;
                    }
                }
            }
        }
        return false;
    }

Print the matrix to the output stream.  Line the elements up in columns.
Use the format object, and right justify within columns of width
characters.
Note that is the matrix is to be read back in, you probably will want
to use a NumberFormat that is set to US Locale.

@param output the output stream.
@param format A formatting object to format the matrix elements
@param width  Column width.
@see DecimalFormat#setDecimalFormatSymbols
public void print(PrintWriter output, NumberFormat format, int width)
    {
        output.println();  // start on new line.
        for (int i = 0; i < m; i++)
        {
            for (int j = 0; j < n; j++)
            {
                String s = format.format(A[i][j]); // format the number
                int padding = Math.max(1, width - s.length()); // At _least_ 1 space
                for (int k = 0; k < padding; k++)
                    output.print(' ');
                output.print(s);
            }
            output.println();
        }
        output.println();   // end with blank line.
    }

    /**
     * Read a matrix from a stream.  The format is the same the print method,
     * so printed matrices can be read back in (provided they were printed using
     * US Locale).  Elements are separated by
     * whitespace, all the elements for each row appear on a single line,
     * the last row is followed by a blank line.
     *
     * @param input the input stream.
     */

    public static Matrix read(BufferedReader input) throws java.io.IOException
    {
        StreamTokenizer tokenizer = new StreamTokenizer(input);

        // Although StreamTokenizer will parse numbers, it doesn't recognize
        // scientific notation (E or D); however, Double.valueOf does.
        // The strategy here is to disable StreamTokenizer's number parsing.
        // We'll only get whitespace delimited words, EOL's and EOF's.
        // These words should all be numbers, for Double.valueOf to parse.

        tokenizer.resetSyntax();
        tokenizer.wordChars(0, 255);
        tokenizer.whitespaceChars(0, ' ');
        tokenizer.eolIsSignificant(true);
        java.util.Vector<Double> vD = new java.util.Vector<Double>();

        // Ignore initial empty lines
        while (tokenizer.nextToken() == StreamTokenizer.TT_EOL) ;
        if (tokenizer.ttype == StreamTokenizer.TT_EOF)
            throw new java.io.IOException("Unexpected EOF on matrix read.");
        do
        {
            vD.addElement(Double.valueOf(tokenizer.sval)); // Read & store 1st row.
        }
        while (tokenizer.nextToken() == StreamTokenizer.TT_WORD);

        int n = vD.size();  // Now we've got the number of columns!
        double row[] = new double[n];
        for (int j = 0; j < n; j++)  // extract the elements of the 1st row.
            row[j] = vD.elementAt(j).doubleValue();
        java.util.Vector<double[]> v = new java.util.Vector<double[]>();
        v.addElement(row);  // Start storing rows instead of columns.
        while (tokenizer.nextToken() == StreamTokenizer.TT_WORD)
        {
            // While non-empty lines
            v.addElement(row = new double[n]);
            int j = 0;
            do
            {
                if (j >= n) throw new java.io.IOException
                        ("Row " + v.size() + " is too long.");
                row[j++] = Double.valueOf(tokenizer.sval).doubleValue();
            }
            while (tokenizer.nextToken() == StreamTokenizer.TT_WORD);
            if (j < n) throw new java.io.IOException
                    ("Row " + v.size() + " is too short.");
        }
        int m = v.size();  // Now we've got the number of rows.
        double[][] A = new double[m][];
        v.copyInto(A);  // copy the rows out of the vector
        return new Matrix(A);
    }


/* ------------------------
   Private Methods
 * ------------------------ */

    /**
     * Check if size(A) == size(B)
     **/

    private void checkMatrixDimensions(Matrix B)
    {
        if (B.m != m || B.n != n)
        {
            throw new IllegalArgumentException("Matrix dimensions must agree.");
        }
    }

    private static final long serialVersionUID = 1;

    public static Matrix zero(int m, int n)
    {
        Matrix A = new Matrix(m, n);
        double[][] X = A.getArray();
        for (int i = 0; i < m; i++)
        {
            for (int j = 0; j < n; j++)
            {
                X[i][j] = 0.0;
            }
        }
        return A;
    }

    public int rows()
    {
        return getRowDimension();
    }

    public int cols()
    {
        return getColumnDimension();
    }

    /**
     * 取出第j列作为一个列向量
     * @param j
     * @return
     */
    public Matrix col(int j)
    {
        double[][] X = new double[m][1];
        for (int i = 0; i < m; i++)
        {
            X[i][0] = A[i][j];
        }
        return new Matrix(X);
    }

    /**
     * 取出第i行作为一个行向量
     * @param i
     * @return
     */
    public Matrix row(int i)
    {
        double[][] X = new double[1][n];
        for (int j = 0; j < n; j++)
        {
            X[0][j] = A[i][j];
        }
        return new Matrix(X);
    }

    public Matrix block(int i, int j, int p, int q)
    {
        return getMatrix(i, i + p - 1, j, j + q - 1);
    }

    /**
     * 返回矩阵的立方（以数组形式）
     * @return
     */
    public double[][] cube()
    {
        double[][] X = new double[m][n];
        for (int i = 0; i < m; i++)
        {
            for (int j = 0; j < n; j++)
            {
                X[i][j] = Math.pow(A[i][j], 3.);
            }
        }

        return X;
    }

    public void setZero()
    {
        for (int i = 0; i < m; i++)
        {
            for (int j = 0; j < n; j++)
            {
                A[i][j] = 0.;
            }
        }
    }

    public void save(DataOutputStream out) throws Exception
    {
        out.writeInt(m);
        out.writeInt(n);
        for (int i = 0; i < m; i++)
        {
            for (int j = 0; j < n; j++)
            {
                out.writeDouble(A[i][j]);
            }
        }
    }

    public boolean load(ByteArray byteArray)
    {
        m = byteArray.nextInt();
        n = byteArray.nextInt();
        A = new double[m][n];
        for (int i = 0; i < m; i++)
        {
            for (int j = 0; j < n; j++)
            {
                A[i][j] = byteArray.nextDouble();
            }
        }
        return true;
    }
}

Creates a ReadResultEntry for data that is readily available in memory.

@param entry               The CacheIndexEntry to use.
@param streamSegmentOffset The Offset in the StreamSegment where to the ReadResultEntry starts at.
@param maxLength           The maximum length of the Read, from the Offset of this ReadResultEntry.
@param updateStats         If true, the entry's cache generation is updated as a result of this call.
@GuardedBy("lock")
    private CacheReadResultEntry createMemoryRead(ReadIndexEntry entry, long streamSegmentOffset, int maxLength, boolean updateStats) {
        assert streamSegmentOffset >= entry.getStreamSegmentOffset() : String.format("streamSegmentOffset{%d} < entry.getStreamSegmentOffset{%d}", streamSegmentOffset, entry.getStreamSegmentOffset());

        int entryOffset = (int) (streamSegmentOffset - entry.getStreamSegmentOffset());

        int length = (int) Math.min(maxLength, entry.getLength() - entryOffset);
        assert length > 0 : String.format("length{%d} <= 0. streamSegmentOffset = %d, maxLength = %d, entry.offset = %d, entry.length = %d", length, streamSegmentOffset, maxLength, entry.getStreamSegmentOffset(), entry.getLength());
        byte[] data = this.cache.get(getCacheKey(entry));
        assert data != null : String.format("No Cache Entry could be retrieved for entry %s", entry);

        if (updateStats) {
            // Update its generation before returning it.
            int generation = this.summary.touchOne(entry.getGeneration());
            entry.setGeneration(generation);
        }

        return new CacheReadResultEntry(entry.getStreamSegmentOffset(), data, entryOffset, length);
    }

// MakeSecret returns a new secret.
func (f *SecretFactory) MakeSecret(args *types.SecretArgs, options *types.GeneratorOptions) (*corev1.Secret, error) {
	var all []kv.Pair
	var err error
	s := f.makeFreshSecret(args)

	pairs, err := keyValuesFromEnvFile(f.ldr, args.EnvSource)
	if err != nil {
		return nil, errors.Wrap(err, fmt.Sprintf(
			"env source file: %s",
			args.EnvSource))
	}
	all = append(all, pairs...)

	pairs, err = keyValuesFromLiteralSources(args.LiteralSources)
	if err != nil {
		return nil, errors.Wrap(err, fmt.Sprintf(
			"literal sources %v", args.LiteralSources))
	}
	all = append(all, pairs...)

	pairs, err = keyValuesFromFileSources(f.ldr, args.FileSources)
	if err != nil {
		return nil, errors.Wrap(err, fmt.Sprintf(
			"file sources: %v", args.FileSources))
	}
	all = append(all, pairs...)

	for _, p := range all {
		err = addKvToSecret(s, p.Key, p.Value)
		if err != nil {
			return nil, err
		}
	}
	if options != nil {
		s.SetLabels(options.Labels)
		s.SetAnnotations(options.Annotations)
	}
	return s, nil
}

