Generate alternative image widths, using either an array of integers, or
a min width, a max width, and a step parameter to fill out the necessary
widths. Existing image alternatives won't be overwritten.

@param  int|int[] $min_width
@param  int       $max_width
@param  int       $step
@return $this
public function derivatives($min_width, $max_width = 2500, $step = 200)
    {
        if (!empty($this->alternatives)) {
            $max = max(array_keys($this->alternatives));
            $base = $this->alternatives[$max];
        } else {
            $base = $this;
        }

        $widths = [];

        if (func_num_args() === 1) {
            foreach ((array) func_get_arg(0) as $width) {
                if ($width < $base->get('width')) {
                    $widths[] = $width;
                }
            }
        } else {
            $max_width = min($max_width, $base->get('width'));

            for ($width = $min_width; $width < $max_width; $width = $width + $step) {
                $widths[] = $width;
            }
        }

        foreach ($widths as $width) {
            // Only generate image alternatives that don't already exist
            if (array_key_exists((int) $width, $this->alternatives)) {
                continue;
            }

            $derivative = MediumFactory::fromFile($base->get('filepath'));

            // It's possible that MediumFactory::fromFile returns null if the
            // original image file no longer exists and this class instance was
            // retrieved from the page cache
            if (null !== $derivative) {
                $index = 2;
                $alt_widths = array_keys($this->alternatives);
                sort($alt_widths);

                foreach ($alt_widths as $i => $key) {
                    if ($width > $key) {
                        $index += max($i, 1);
                    }
                }

                $basename = preg_replace('/(@\d+x){0,1}$/', "@{$width}w", $base->get('basename'), 1);
                $derivative->setImagePrettyName($basename);

                $ratio = $base->get('width') / $width;
                $height = $derivative->get('height') / $ratio;

                $derivative->resize($width, $height);
                $derivative->set('width', $width);
                $derivative->set('height', $height);

                $this->addAlternative($ratio, $derivative);
            }
        }

        return $this;
    }

Returns an instance of a translator that was configured for the name and passed
locale. If no locale is passed then it takes the value returned by the `getLocale()` method.

This method can be used to configure future translators, this is achieved by passing a callable
as the last argument of this function.

### Example:

```
I18n::setTranslator('default', function () {
$package = new \Aura\Intl\Package();
$package->setMessages([
'Cake' => 'Gâteau'
]);
return $package;
}, 'fr_FR');

$translator = I18n::translator('default', 'fr_FR');
echo $translator->translate('Cake');
```

You can also use the `Cake\I18n\MessagesFileLoader` class to load a specific
file from a folder. For example for loading a `my_translations.po` file from
the `src/Locale/custom` folder, you would do:

```
I18n::translator(
'default',
'fr_FR',
new MessagesFileLoader('my_translations', 'custom', 'po');
);
```

@deprecated 3.5 Use getTranslator() and setTranslator()
@param string $name The domain of the translation messages.
@param string|null $locale The locale for the translator.
@param callable|null $loader A callback function or callable class responsible for
constructing a translations package instance.
@return \Aura\Intl\TranslatorInterface|null The configured translator.
@throws \Aura\Intl\Exception
public static function translator($name = 'default', $locale = null, callable $loader = null)
    {
        deprecationWarning(
            'I18n::translator() is deprecated. ' .
            'Use I18n::setTranslator()/getTranslator() instead.'
        );
        if ($loader !== null) {
            static::setTranslator($name, $loader, $locale);

            return null;
        }

        return self::getTranslator($name, $locale);
    }

Wrap the given data if necessary.

@param  array  $data
@param  array  $with
@param  array  $additional
